const t=k=>I18N[state.lang][k]||k;
async function api(p,opts){const r=await fetch(p,opts);if(!r.ok)throw new Error(await r.text());return r.json()}
async function loadSnapshot(){if(window.FI2A_PUBLIC_SNAPSHOT)return window.FI2A_PUBLIC_SNAPSHOT;return api('/api/snapshot')}
function setLang(lang){state.lang=lang;document.documentElement.lang=lang;$$('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n)});renderGates();renderMetrics();renderEntityBrowser();if(state.snapshot){runAsk();runInvestigate();runDiscover();if($('#searchQ').value.trim())runSearch()}}
function nameOf(id){return state.entityMap.get(id)?.legal_name||id||'—'}
function metricOf(code){return state.metricMap.get(code)||{code,name:code,families:[]}}
function sourceOf(id){return state.sourceMap.get(id)||null}
function val(o){if(!o)return'—';if(o.numeric_value_real!=null){const u=String(o.unit||'');if(u.toLowerCase()==='ratio')return`${fmt(Number(o.numeric_value_real)*100)} %`;if(u==='PERCENT')return`${fmt(o.numeric_value_real)} %`;return`${fmt(o.numeric_value_real)} ${esc(u)}`.trim()}return esc(o.text_value||o.numeric_value_text||'—')}
function badge(s,c=''){return`<span class="badge ${c}">${esc(s)}</span>`}
function sourceLocator(o){if(!o)return t('locatorNotRecorded');const xs=[];if(o.source_page)xs.push(`${t('pageLocator')}: ${o.source_page}`);if(o.source_table)xs.push(`${t('tableLocator')}: ${o.source_table}`);if(o.source_datapoint)xs.push(`${t('datapointLocator')}: ${o.source_datapoint}`);return xs.length?xs.join(' · '):t('locatorNotRecorded')}
function sourceLine(o){const s=sourceOf(o?.source_id);return s?`${esc(s.publisher||'')} · ${esc(s.title||'')} · ${esc(sourceLocator(o))}`:'—'}
function scopeLabel(v){return v==='EBA_HIGHEST_LEVEL_OF_CONSOLIDATION'?t('scopeEbaHighest'):v}
function factCard(o,context=''){if(!o)return`<div class="empty">${t('noFact')}</div>`;const m=metricOf(o.metric_code),s=o.semantic||{},scope=o.consolidation_scope||s.consolidation_scope||t('notRecorded');return`<article class="card fact"><div class="eyebrow">${esc(o.epistemic_class||'FACT')}</div><h4>${esc(nameOf(o.entity_id))}</h4><div class="big">${val(o)}</div><div>${esc(m.name||m.code)}</div>${context?`<div class="source-line"><strong>${esc(context)}</strong></div>`:''}<div class="badges">${badge(o.reference_date||t('notRecorded'))}${badge(s.reporting_framework||'UNRESOLVED')}${badge(scopeLabel(scope))}${o.uncertain?badge('UNCERTAIN','warn'):''}</div><div class="source-line">${sourceLine(o)}</div><button class="mini audit-link" data-id="${esc(o.id)}">${t('auditButton')}</button></article>`}
function jsonObj(v){if(v&&typeof v==='object')return v;try{return JSON.parse(v||'{}')}catch{return{}}}
function sourceQualityIssuesForEntity(eid){
  const obs=state.snapshot.observations.filter(o=>o.entity_id===eid),obsIds=new Set(obs.map(o=>o.id)),sourceIds=new Set(obs.map(o=>o.source_id));
  return(state.snapshot.source_quality_issues||[]).map(q=>({q,d:jsonObj(q.origin_record_json)})).filter(x=>{
    if(x.d.canonical_entity_id===eid)return true;
    if(Array.isArray(x.d.affected_observation_ids)&&x.d.affected_observation_ids.some(id=>obsIds.has(id)))return true;
    const sid=x.d.source_document_id||x.d.canonical_source_id;return !!sid&&sourceIds.has(sid);
  });
}
function sourceQualityHtml(eid){
  const xs=sourceQualityIssuesForEntity(eid);if(!xs.length)return'';
  return`<div class="source-quality"><h4>${t('sourceQuality')}</h4><div class="candidate-grid">${xs.map(({q,d})=>{
    const status=d.value_resolution_status||d.conflict_status||d.issue_type||'SOURCE_QUALITY_NOTICE';
    const witnesses=Array.isArray(d.witnesses)&&d.witnesses.length?`<details><summary>${t('sourceQualityWitnesses')} · ${d.witnesses.length}</summary><ul>${d.witnesses.map(w=>`<li><b>${esc(w.witness_type||'SOURCE')}</b> · ${esc(w.source_raw_value??w.numeric_value_real??'—')} · ${esc(w.unit||'')} · ${esc(w.source_page_1based?('p. '+w.source_page_1based):'')}</li>`).join('')}</ul></details>`:'';
    return`<article class="candidate source-quality-notice"><div class="eyebrow">${esc(d.issue_type||'SOURCE_QUALITY')}</div>${badge(status,'warn')}<h4>${esc(d.external_issue_id||q.origin_id||'SOURCE_QUALITY_NOTICE')}</h4><p>${esc(d.description||'')}</p>${d.value_resolution_status==='UNRESOLVED_NO_WINNER'?`<p><strong>${esc(t('sourceQualityUnresolved'))}</strong></p>`:''}${witnesses}<code>${esc(q.origin_id||d.source_quality_issue_id||'')}</code></article>`;
  }).join('')}</div></div>`;
}
function regimes(eid){return state.snapshot.regime_memberships.filter(x=>x.entity_id===eid&&String(x.status||'').startsWith('ACTIVE')).map(x=>x.regime_code)}
function latestRows(eid,mc){const xs=state.snapshot.observations.filter(o=>o.entity_id===eid&&o.metric_code===mc);if(!xs.length)return[];const d=xs.reduce((m,o)=>(o.reference_date||'')>m?(o.reference_date||''):m,'');return xs.filter(o=>(o.reference_date||'')===d)}
function unresolvedGovernanceForRows(eid,rows){if(rows.length<2)return null;const ids=new Set(rows.map(o=>o.id));for(const q of(state.snapshot.source_quality_issues||[])){const d=jsonObj(q.origin_record_json),affected=Array.isArray(d.affected_observation_ids)?d.affected_observation_ids:[];if(d.canonical_entity_id!==eid||d.value_resolution_status!=='UNRESOLVED_NO_WINNER'||d.selection_policy!=='NO_CANONICAL_VALUE_SELECTION'||affected.length<2)continue;if(rows.every(o=>affected.includes(o.id))&&affected.every(id=>ids.has(id)))return{q,d}}return null}
function resolveLatestEvidence(eid,mc){const observations=latestRows(eid,mc),referenceDate=observations[0]?.reference_date||null;if(!observations.length)return{state:'NONE',entity_id:eid,metric_code:mc,reference_date:null,observations:[],governance:null,reason:'NO_OBSERVATION'};if(observations.length===1)return{state:'SINGLE',entity_id:eid,metric_code:mc,reference_date:referenceDate,observations,governance:null,reason:null};const governance=unresolvedGovernanceForRows(eid,observations);return governance?{state:'UNRESOLVED_CONFLICT',entity_id:eid,metric_code:mc,reference_date:referenceDate,observations,governance,reason:'UNRESOLVED_SOURCE_CONFLICT'}:{state:'MULTIPLE_ROWS',entity_id:eid,metric_code:mc,reference_date:referenceDate,observations,governance:null,reason:'MULTIPLE_LATEST_ROWS'}}
function ordinaryScalarAllowed(r){return !!r&&r.state==='SINGLE'&&r.observations?.length===1}
function latest(eid,mc){const r=resolveLatestEvidence(eid,mc);return ordinaryScalarAllowed(r)?r.observations[0]:null}
function rowEvidenceLabel(o,i,n){const s=o.semantic||{},d=s.selected_dimensions&&typeof s.selected_dimensions==='object'?s.selected_dimensions:{},parts=[];if(s.view_key)parts.push(`view=${s.view_key}`);if(s.view_role)parts.push(`role=${s.view_role}`);if(s.variant_key)parts.push(`variant=${s.variant_key}`);for(const k of['country','country_code','ltg_treatment','transitional_treatment','model_basis','volatility_adjustment','volatility_adjustment_state','denominator_basis','entity_scope_key','source_row_code','source_column_code','required_view_code']){const v=d[k];if(v!=null&&typeof v!=='object'&&!parts.some(x=>x.endsWith('='+v)))parts.push(`${k}=${v}`);if(parts.length>=4)break}if(o.source_datapoint)parts.push(`${t('datapointLocator')}=${o.source_datapoint}`);return parts.slice(0,5).join(' · ')||`${t('evidenceRows')} ${i+1}/${n}`}
function resolutionNoticeHtml(r){if(!r||r.state==='NONE')return`<div class="empty">${t('noFact')}</div>`;if(r.state==='SINGLE')return'';const conflict=r.state==='UNRESOLVED_CONFLICT';return`<article class="candidate source-quality-notice"><div class="eyebrow">${esc(conflict?t('unresolvedConflictTitle'):t('multipleRowsTitle'))}</div>${badge(conflict?t('unresolvedShort'):t('multipleRowsShort'),'warn')}<h4>${esc(nameOf(r.entity_id))} · ${esc(metricOf(r.metric_code).name||r.metric_code)}</h4><p>${esc(conflict?t('unresolvedConflictHelp'):t('multipleRowsHelp'))}</p><div class="badges">${badge(`${t('latestDate')}: ${r.reference_date||t('notRecorded')}`)}${badge(`${t('evidenceRows')}: ${r.observations.length}`)}</div></article>`}
function resolutionCardsHtml(r){if(!r||r.state==='NONE')return`<div class="empty">${t('noFact')}</div>`;if(r.state==='SINGLE')return factCard(r.observations[0]);return`${resolutionNoticeHtml(r)}<div class="card-grid">${r.observations.map((o,i)=>factCard(o,rowEvidenceLabel(o,i,r.observations.length))).join('')}</div>`}
function observationResolution(o){if(!o)return null;const r=resolveLatestEvidence(o.entity_id,o.metric_code);return r.observations.some(x=>x.id===o.id)?r:null}
function observationContextLabel(o){const r=observationResolution(o);if(!r||r.state==='SINGLE'||r.state==='NONE')return'';return`${r.state==='UNRESOLVED_CONFLICT'?t('unresolvedConflictTitle'):t('multipleRowsTitle')} · ${t('evidenceRows')}: ${r.observations.length}`}
function entityEmptyStateHtml(eid){return state.snapshot.observations.some(o=>o.entity_id===eid)?'':`<div class="empty">${esc(t('noObservations'))}</div>`}
function entityMetrics(eid){return[...new Set(state.snapshot.observations.filter(o=>o.entity_id===eid).map(o=>o.metric_code))].sort()}
function dossierHtml(eid){const e=state.entityMap.get(eid),obs=state.snapshot.observations.filter(o=>o.entity_id===eid),src=new Set(obs.map(o=>o.source_id)),rel=state.snapshot.relations.filter(r=>r.subject_entity_id===eid||r.object_entity_id===eid),periods=[...new Set(obs.map(o=>o.reference_date).filter(Boolean))].sort();return`<div class="dossier"><h4>${esc(e?.legal_name||eid)}</h4><div class="kv"><span>${t('type')}</span><b>${esc(e?.type||'—')}</b><span>${t('country')}</span><b>${esc(e?.country||'—')}</b><span>${t('regimes')}</span><b>${esc(regimes(eid).join(', ')||'—')}</b><span>${t('facts')}</span><b>${obs.length}</b><span>${t('sources')}</span><b>${src.size}</b><span>${t('relations')}</span><b>${rel.length}</b><span>${t('periods')}</span><b>${periods[0]||'—'} → ${periods.at(-1)||'—'}</b></div></div>`}
