function svgSeries(xs){const ys=xs.filter(o=>o.numeric_value_real!=null);if(ys.length<2)return`<div class="empty">${t('noResults')}</div>`;const W=760,H=230,p=30,min=Math.min(...ys.map(o=>Number(o.numeric_value_real))),max=Math.max(...ys.map(o=>Number(o.numeric_value_real))),span=max-min||1,pts=ys.map((o,i)=>[p+i*(W-2*p)/(ys.length-1),H-p-(Number(o.numeric_value_real)-min)*(H-2*p)/span,o]),path=pts.map((x,i)=>(i?'L':'M')+x[0].toFixed(1)+','+x[1].toFixed(1)).join(' ');return`<svg viewBox="0 0 ${W} ${H}" class="chart"><path d="${path}" fill="none" stroke="currentColor" stroke-width="3"/>${pts.map(x=>`<circle cx="${x[0]}" cy="${x[1]}" r="4"><title>${esc(x[2].reference_date)} · ${fmt(x[2].numeric_value_real)}</title></circle>`).join('')}</svg><div class="series-table">${ys.map(o=>`<div><span>${esc(o.reference_date)}</span><b>${val(o)}</b><small>${esc(o.restatement_version||'')}</small></div>`).join('')}</div>`}
